#!/usr/bin/env sh

# Synopsis:
# Build a template project for each project shape in /opt/test-runner/shapes. The Dockerfile runs
# this once, at image build. The runner's fast path (src/Exercism.TestRunner.VBNet/FastPath.vb)
# then reuses what each build leaves behind:
# - vbc.rsp: the exact compiler command line produced by MSBuild for that project file.
# - obj/: the source files generated by the SDK and the packages (assembly attributes, the test
#   entry point and so on).
# - publish/: every dependency, precompiled with ReadyToRun, so that the test executable spends
#   less time in the JIT compiler on each run.
# - shape.key: the key that identifies the shape (written by the runner's --prepare-shape option).
# If a shape fails to build, this script removes it, and solutions with that shape use MSBuild.

# The Dockerfile mounts the ReadyToRun compiler and the runtime packs at /r2r-packages for this script only.
for package in /r2r-packages/*; do
    ln -s "${package}" "/root/.nuget/packages/$(basename "${package}")"
done

for dir in /opt/test-runner/shapes/*/; do
    cd "${dir}" || exit 1
    # The runner fills in each solution's root namespace, so the template uses the default one (its own name).
    sed -i '/<RootNamespace>/d' ExercismShape.vbproj
    printf 'Public Module ExercismShapeStub\nEnd Module\n' > ExercismShape.vb
    printf 'Imports Xunit\n\nPublic Class ExercismShapeTests\n    <Fact>\n    Public Sub Passes()\n    End Sub\nEnd Class\n' > ExercismShapeTests.vb
    # This target writes the compiler arguments to vbc.rsp after MSBuild has compiled the project.
    cat > Directory.Build.targets <<'TARGETS'
<Project>
  <Target Name="ExercismCaptureCompilerArguments" AfterTargets="CoreCompile" Condition="'$(ExercismCaptureCompilerArguments)' == 'true'">
    <WriteLinesToFile File="$(MSBuildProjectDirectory)/vbc.rsp" Lines="@(VbcCommandLineArgs)" Overwrite="true" />
  </Target>
</Project>
TARGETS

    if dotnet build -c release --source /root/.nuget/packages/ -p:ProvideCommandLineArgs=true -p:ExercismCaptureCompilerArguments=true -nologo -v q &&
       dotnet publish -c release --source /root/.nuget/packages/ --use-current-runtime --self-contained false -p:PublishReadyToRun=true -o publish -nologo -v q &&
       # MSBuild turns every backslash in an item into a slash on Linux, which breaks the escaped
       # quotes in the /define: argument (CONFIG=\"release\"). This puts the backslashes back.
       sed -i '/^\/define:/ s|/"|\\"|g' vbc.rsp &&
       /opt/test-runner/Exercism.TestRunner.VBNet --prepare-shape "${dir%/}"; then
        echo "Built shape ${dir}"
    else
        echo "Skipping shape ${dir}"
        rm -rf "${dir}"
    fi
done

# Many shapes share the same dependency files. Hard links keep one copy of each in the image.
find /opt/test-runner/shapes -type f -path '*/publish/*' -exec sha256sum {} + | sort | awk '
    $1 == previous { system("ln -f \"" first "\" \"" $2 "\"") ; next }
    { previous = $1; first = $2 }'

# Remove the links again, so that the ReadyToRun compiler and the runtime packs do not stay in the image.
for package in /r2r-packages/*; do
    rm "/root/.nuget/packages/$(basename "${package}")"
done
